/* Fade in and lift 14px over the first quarter of the element's trip through the window.
   --rho-step delays the start a little per step, so a row of cards arrives one by one. */
@supports (animation-timeline: view()) {
  @media (prefers-reduced-motion: no-preference) {
    .rho-reveal {
      animation: rho-reveal-rise linear both;
      animation-timeline: view();
      animation-range: entry calc(var(--rho-step, 0) * 10%) cover calc(20% + var(--rho-step, 0) * 4%);
    }
  }
}

@keyframes rho-reveal-rise {
  from { opacity: 0; transform: translateY(14px); }
  to { opacity: 1; transform: translateY(0); }
}

import type { CSSProperties, ReactNode } from "react";
import { cn } from "@foundry/foundry-utils";
import "./rho-reveal.css";

export interface RhoRevealProps {
  children: ReactNode;
  /** stagger step: 0 arrives first, 1 a little later, and so on */
  step?: number;
  /** element to render */
  as?: "div" | "li" | "p";
  className?: string;
}

export function RhoReveal({ children, step = 0, as: Tag = "div", className }: RhoRevealProps) {
  return (
    <Tag className={cn("rho-reveal", className)} style={{ "--rho-step": step } as CSSProperties}>
      {children}
    </Tag>
  );
}
